UPDATE achievements SET i18n = '{"lv":{"title":"Nakts pētnieks","description":"Izpildi izaicinājumu no 21:00 līdz 3:00."},"ru":{"title":"Ночной исследователь","description":"Выполните задание с 21:00 до 3:00."}}'::jsonb WHERE id = 'night-explorer';
UPDATE achievements SET i18n = '{"lv":{"title":"Nedēļas varonis","description":"Sasniedz 4 nedēļas mērķus."},"ru":{"title":"Герой недели","description":"Выполните 4 недельные цели."}}'::jsonb WHERE id = 'weekly-warrior';
